import {addUsage, shouldContinueToolLoop} from './orchestratorHelpers.js';
import type {ToolRegistry} from './tools/registry.js';
import type {ToolCall, UsageMetadata} from '../types/ai.js';

// All three conditions matter; dropping the registry check spins the tool loop.

const A_TOOL: ToolCall[] = [{id: 't1', name: 'lookup', input: {}}];
const REGISTRY = {} as ToolRegistry;

describe('shouldContinueToolLoop', () => {
  it('continues when the model requested a tool and a registry can run it', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, REGISTRY)).toBe(true);
  });

  it('stops when no registry is configured, whatever the model asked for', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, undefined)).toBe(false);
  });

  it('stops when the model named no tool', () => {
    expect(shouldContinueToolLoop('tool_use', [], REGISTRY)).toBe(false);
  });

  it('stops when the model finished for a reason other than tool use', () => {
    expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
  });
});

// specs/hal-engine-config-hooks/spec.md: afterModelResponse receives the summed provider-call usage for the turn.
describe('addUsage', () => {
  const ROUND: UsageMetadata = {inputTokens: 2, outputTokens: 1, totalTokens: 3};

  it('sums each token field across rounds and skips rounds that reported no usage', () => {
    const rounds = [ROUND, undefined, {inputTokens: 7, outputTokens: 4, totalTokens: 11}];

    expect(rounds.reduce(addUsage, undefined)).toEqual({inputTokens: 9, outputTokens: 5, totalTokens: 14});
  });

  it('leaves the total undefined when no round reported usage', () => {
    expect([undefined, undefined].reduce(addUsage, undefined)).toBeUndefined();
  });
});
specs/hal-engine-config-hooks/spec.md:25:- `afterModelResponse` is called once per user message after the round loop exits and receives the summed provider-call usage for the entire turn, so tool rounds are included in a deployer's billing or audit total ([validated by: reports the summed usage from every provider call in a turn with two tool rounds](../../src/orchestration/chatOrchestratorUsage.acceptance.test.ts#L44)).
specs/hal-engine-config-hooks/spec.md:26:- A round whose provider reported no usage adds nothing to that total rather than voiding it ([validated by: sums each token field across rounds and skips rounds that reported no usage](../../src/orchestration/orchestratorHelpers.test.ts#L32), [validated by: counts reported rounds while leaving a turn with no reported usage undefined](../../src/orchestration/chatOrchestratorUsage.acceptance.test.ts#L67)).
specs/hal-engine-config-hooks/spec.md:27:- A turn in which no provider call reported usage hands the hook `undefined`, exactly as before ([validated by: leaves the total undefined when no round reported usage](../../src/orchestration/orchestratorHelpers.test.ts#L38)).

